[ -e claude-baseline-comparison.json ] && exit 9; python3 - <<'EOF'
import json
def diff(a,b,p=''):
    if type(a)!=type(b): return [(p,'type')]
    if isinstance(a,dict):
        out=[]
        for k in sorted(set(a)|set(b)):
            if k not in a or k not in b: out.append((p+'/'+k,'missing'))
            else: out+=diff(a[k],b[k],p+'/'+k)
        return out
    if isinstance(a,list):
        if len(a)!=len(b): return [(p,'len %d!=%d'%(len(a),len(b)))]
        out=[]
        for i,(x,y) in enumerate(zip(a,b)): out+=diff(x,y,p+'/%d'%i)
        return out
    return [] if a==b else [(p,'value')]
pairs=[('claude-runtime-before.json','runtime-before.json'),('claude-runtime-after.json','runtime-after.json'),('claude-runtime-after.json','claude-runtime-before.json'),
('claude-api.json','api-primary.json'),('claude-cli74.json','cli74-primary.json'),('claude-curly.json','curly-primary.json'),('claude-additions.json','additions-primary.json')]
for f,g in pairs:
    d=diff(json.load(open(f)),json.load(open(g)))
    print(f,'vs',g,len(d)); [print('  ',x) for x in d[:40]]
EOF
